Here's an example program in C++ that reads a text file line by line and counts the number of occurrences of a specific word in the file:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <sstream>

using namespace std;

int main() {
    // Define the name of the input file
    const string INPUT_FILE_NAME = "input.txt";

    // Declare variables to store input and output
    string line, word;
    int count = 0;

    // Open the input file in read mode
    ifstream input_file(INPUT_FILE_NAME);

    // Check if the file was successfully opened
    if (!input_file) {
        cerr << "Error: Failed to open input file." << endl;
        return 1;
    }

    // Declare a stringstream to read the file line by line
    stringstream line_stream;

    // Read each line from the input file and process it
    while (getline(input_file, line)) {
        // Add the current line to the stringstream
        line_stream << line;

        // Stringstream now contains the contents of the current line
        while (line_stream >> word) {
            // Check if the specified word matches the current word
            if (word == "search_word") {
                // If a match is found, increment the word count
                count++;
            }

            // Discard the remaining characters in the stringstream until the next delimiter
            line_stream.ignore(numeric_limits<streamsize>::max(), line_stream.rdbuf()->sgetc());
        }
    }

    // Close the input file
    input_file.close();

    // Output the word count
    cout << "Number of occurrences of 'search_word': " << count << endl;

    return 0;
}
```

